	L["For all of the social options above, you can treat guild members as friends too."] = "Für alle oben genannten sozialen Optionen kannst du Gildenmitglieder ebenfalls wie Freunde behandeln."
	L["For Great Honor"] = "Große Ehre"
	L["Four minutes"] = "Vier Minuten"
	L["Frames"] = "Fenster"
	L["Frostmaul E'ko"] = "E'ko der Frosthagelriesen"
	L["Frostsaber E'ko"] = "E'ko der Frostsäbler"
	L["Game Options"] = "Spieloptionen"
	L["General"] = "allgemein"
	L["Ghostlands"] = "Geisterlande"
	L["Glowing Scorpid Blood"] = "Leuchtendes Skorpidblut"
	L["Gnomeregan"] = "Gnomeregan"
	L["Gold Only"] = "Ausschließlich Gold"
	L["Gossip frame not open."] = "Gesprächsfenster nicht geöffnet."
	L["Graphics and Sound"] = "Grafik und Sound"
	L["Green Fireworks"] = "Grünes Feuerwerk"
	L["Green Iron Bracers"] = "Grüne Eisenarmschienen"
	L["Groups"] = "Gruppen"
	L["Guild"] = "Gilde"
	L["Gurubashi, Vilebranch, and Witherbark Coins"] = "Münzen der Gurubashi, Vilebranch und Witherbark"
	L["Gyrocopters"] = "Gyrocopter"
	L["H"] = "H"
	L["Have mats?"] = "Material vorhanden?"
	L["Heavy Grinding Stone"] = "Schwerer Schleifstein"
	L["Hellfire Peninsula"] = "Höllenfeuerhalbinsel"
	L["Helm"] = "Helm"
	L["Help"] = "Hilfe"
	L["Help contribute flight times"] = "Helfen, Flugzeiten beizutragen"
	L["Hide addon buttons"] = "Addon-Schaltflächen verstecken"
	L["Hide chat buttons"] = "Chat-Buttons verstecken"
	L["Hide cooldown duration numbers (if enabled)"] = "Nummern der Cooldown Anzeige verbergen (wenn aktiviert)"
	L["Hide error messages"] = "Fehlermeldungen verstecken"
	L["Hide gryphons"] = "Greifenpaar verstecken"
	L["Hide keybind text"] = "Tastenbelegungstext verstecken"
	L["Hide macro text"] = "Makrotext verstecken"
	L["Hide portrait numbers"] = "Portraitnummern verbergen"
	L["Hide raid group labels"] = "Schlachtzugsgruppenbeschriftungen verstecken"
	L["Hide stance bar"] = "Haltungsleiste verstecken"
	L["Hide the clock"] = "Uhr verstecken"
	L["Hide the combat log"] = "Kampflog verstecken"
	L["Hide the day and night indicator"] = "Tag- und Nachtanzeige verstecken"
	L["Hide the health bar"] = "Gesundheitsleiste verstecken"
	L["Hide the Looking for Group button"] = "Schaltfläche für die Gruppensuche verstecken"
	L["Hide the tracking button"] = "Verfolgungsschaltfläche verstecken"
	L["Hide the zone text bar"] = "Verstecke die Zonen-Text Leiste"
	L["Hide the zoom buttons"] = "Zoom Buttons verbergen"
	L["Hide tooltips"] = "Tooltips verstecken"
	L["Hide tooltips for world units during combat"] = "Im Kampf Tooltips für Welt Einheiten verstecken"
	L["Hide zone text"] = "Gebietstext verbergen"
	L["High"] = "Hoch"
	L["Hillsbrad Foothills"] = "Vorgebirge des Hügellands"
	L["Hinterlands"] = "Hinterlande"
	L["Hold ALT and drag the flight map to move it."] = "Halte ALT gedrückt und ziehe die Flugkarte, um sie zu verschieben."
	L["Home"] = "Startseite"
	L["hop"] = "Zwischenstopp"
	L["Horsesteps"] = "Pferdeschritte"
	L["Hover the pointer over a button."] = "Bewege den Mauszeiger über eine Schaltfläche."
	L["Hyjal Summit"] = "Hyjalgipfel"
	L["Ice Thistle E'ko"] = "E'ko der Eisdistelyetis"
	L["Icon size"] = "Symbolgröße"
	L["If checked, a bag search box will be shown in the backpack frame and the bank frame."] = "Wenn diese Option aktiviert ist, wird im Rucksackrahmen und im Bankrahmen ein Taschen-Suchfeld angezeigt."
	L["If checked, a button will be added to the character frame which will show your equipped item durability when you hover the pointer over it.|n|nIn addition, an overall percentage will be shown in the chat frame when you die."] = "Wenn ausgewählt, wird ein Button zum Charakter-Fenster hinzugefügt. Wenn der Mousezeiger über diesem Button ist, wird die Ausrüstungs Haltbarkeit angezeigt.|n|nZusätzlich wird beim Sterben, ein Gesamt-Prozentsatz Wert im Chat ausgegeben."
	L["If checked, a cancel form button will be shown on the flight map while you are playing as a shapeshifted druid or shaman."] = "Wenn ausgewählt, wird auf der Flugkarte eine Schaltfläche zum Abbrechen der Gestalt angezeigt, während du als verwandelter Druide oder Schamane spielst."
	L["If checked, a group invite will be sent to anyone who whispers you with a set keyword as long as you are ungrouped, group leader or raid assistant and not queued for a battleground or the Looking for Group feature.|n|nFriends who message the keyword using Battle.net will not be sent a group invite if they are appearing offline.  They need to either change their online status or use character whispers."] = "Wenn ausgewählt, wird jedem, der dir das festgelegte Schlüsselwort flüstert, eine Gruppeneinladung gesendet, sofern du nicht in einer Gruppe, Gruppenleiter oder Schlachtzugsassistent bist und dich nicht in der Warteschlange für ein Schlachtfeld oder die Gruppensuche befindest.|n|nFreunde, die das Schlüsselwort über Battle.net senden, erhalten keine Gruppeneinladung, wenn sie als offline angezeigt werden.  Sie müssen entweder ihren Onlinestatus ändern oder Charakter-Flüsternachrichten verwenden."
	L["If checked, a master volume slider will be shown in the character frame."] = "Wenn ausgewählt, wird ein Gesamtlautstärke-Regler im Charakter-Fenster angezeigt."
	L["If checked, a minimap button will be available.|n|nClick - Toggle options panel.|n|nSHIFT-click - Toggle music.|n|nALT-click - Toggle errors (if enabled).|n|nCTRL/SHIFT-click - Toggle windowed mode.|n|nCTRL/ALT-click - Toggle Zygor (if installed)."] = "Wenn ausgewählt, steht eine Minikartenschaltfläche zur Verfügung.|n|nKlick - Optionsfenster umschalten.|n|nUMSCHALT-Klick - Musik umschalten.|n|nALT-Klick - Fehlermeldungen umschalten (falls aktiviert).|n|nSTRG/UMSCHALT-Klick - Fenstermodus umschalten.|n|nSTRG/ALT-Klick - Zygor umschalten (falls installiert)."
	L["If checked, a power bar will be shown in the player frame when you are playing a shapeshifted druid."] = "Wenn ausgewählt, wird im Spielerfenster eine Kraftleiste angezeigt, wenn du einen verwandelten Druiden spielst."
	L["If checked, a repair summary will be shown in chat when your gear is automatically repaired."] = "Wenn ausgewählt, wird im Chat eine Reparaturzusammenfassung angezeigt, wenn deine Ausrüstung automatisch repariert wird."
	L["If checked, a timer will be shown under the PvP encounter ready frame so that you know how long you have left to click the enter button."] = "Wenn ausgewählt, wird unter dem Bereitschaftsfenster für PvP-Begegnungen ein Timer angezeigt, damit du weißt, wie viel Zeit dir noch bleibt, um auf die Betreten-Schaltfläche zu klicken."
	L["If checked, a train all skills button will be shown in the skill trainer frame allowing you to train all available skills instantly."] = "Wenn ausgewählt, wird im Lehrerfenster eine Schaltfläche angezeigt, mit der du alle verfügbaren Fertigkeiten sofort erlernen kannst."
	L["If checked, a vendor summary will be shown in chat when junk is automatically sold."] = "Wenn ausgewählt, wird im Chat eine Händlerzusammenfassung angezeigt, wenn Plunder automatisch verkauft wird."
	L["If checked, A'dal in Shattrath City will be muted."] = "Wenn ausgewählt, wird A'dal in Shattrath stummgeschaltet."
	L["If checked, additional font sizes will be available in the chat frame font size menu."] = "Wenn ausgewählt, stehen im Menü für die Schriftgröße des Chatfensters zusätzliche Schriftgrößen zur Verfügung."
	L["If checked, additional functionality will be added to the auction house.|n|nBuyout only - create buyout auctions without filling in the starting price.|n|nGold only - set the copper and silver prices at 99 to speed up new auctions.|n|nFind item - search the auction house for the item you are selling.|n|nIn addition, the auction duration setting will be saved account-wide."] = "Wenn ausgewählt, werden dem Auktionshaus zusätzliche Funktionen hinzugefügt.|n|nNur Sofortkauf - erstelle Sofortkaufauktionen, ohne den Startpreis auszufüllen.|n|nNur Gold - setzt die Kupfer- und Silberpreise auf 99, um neue Auktionen zu beschleunigen.|n|nGegenstand finden - durchsucht das Auktionshaus nach dem Gegenstand, den du verkaufst.|n|nAußerdem wird die Einstellung der Auktionsdauer accountweit gespeichert."
	L["If checked, addon buttons will be hidden while the pointer is not over the minimap."] = "Wenn ausgewählt, werden Addon-Schaltflächen versteckt, solange sich der Mauszeiger nicht über der Minikarte befindet."
	L["If checked, all grey items in your bags will be sold automatically when you visit a merchant.|n|nYou can hold the shift key down when you talk to a merchant to override this setting."] = "Wenn ausgewählt, werden alle grauen Gegenstände in deinen Taschen automatisch verkauft wenn du mit einem Händler sprichst.|n|nHalte die SHIFT-Taste gedrückt wenn du mit einem Händler sprichst um diese Funktion aufzuheben."
	L["If checked, an animation slider will be shown in the dressing room."] = "Wenn ausgewählt, wird in der Anprobe ein Animationsregler angezeigt."
	L["If checked, available quests will be accepted automatically."] = "Wenn ausgewählt, werden verfügbare Quests automatisch akzeptiert."
	L["If checked, BattleTag and Real ID friend requests will be automatically declined.|n|nEnabling this option will automatically decline any pending requests."] = "Wenn ausgewählt, werden BattleTag und Real ID Freundschaftsanfragen automatisch abgelehnt.|n|nDurch das Aktivieren der Option, werden alle ausstehenden Anfragen automatisch abgelehnt."
	L["If checked, chat frame buttons will be hidden.|n|nClicking chat tabs will automatically show the latest messages.|n|nUse the mouse wheel to scroll through the chat history.  Hold down SHIFT for page jump or CTRL to jump to the top or bottom of the chat history."] = "Wenn ausgewählt, werden die Chat-Fenster Buttons versteckt.|n|nBei einem Klick auf die Chat Reiter/Tabs werden automatisch die letzten Nachrichten angezeigt.|n|nBenutz das Mausrad um durch den Chat Verlauf zu scrollen. Halte die SHIFT-Taste um einen Seite weit zu springen, oder die STRG-Taste um zum Anfang oder Ende des Chat Verlaufs zu springen."
	L["If checked, chat text will not fade out after a time period."] = "Wenn ausgewählt, wird der Chat Text nach einer Zeit nicht mehr automatisch verblassen."
	L["If checked, class coloring will be used in the player frame and target frame."] = "Wenn ausgewählt, wird die Klassenfarbe für das Spieler und Ziel benutzt."
	L["If checked, class colors will be used in the chat frame."] = "Wenn diese Option aktiviert ist, werden im Chatfenster Klassenfarben verwendet."
	L["If checked, clock hourly chimes will be muted."] = "Wenn ausgewählt, werden die stündlichen Glockenschläge der Uhr stummgeschaltet."
	L["If checked, completed quests will be turned-in automatically."] = "Wenn ausgewählt, werden abgeschlossene Quests automatisch abgegeben."
	L["If checked, confirmations will no longer appear when you choose a loot roll option or attempt to sell or mail a tradable item."] = "Wenn ausgewählt, werden Bestätigungen nicht länger angezeigt wenn du auf einen erbeuteten Gegenstand würfelst oder einen handelbaren Gegenstand verkaufst oder per Post verschickst."
	L["If checked, cooldown duration numbers will not be shown over the cooldowns.|n|nIf unchecked, cooldown duration numbers will be shown over the cooldowns if they are enabled in the game options panel ('ActionBars' menu)."] = "Wenn ausgewählt, werden keine Zahlen für Abklingzeiten angezeigt.|n|nWenn nicht ausgewählt, wird ein numerischer Countdown für Abklingzeiten angezeigt, sofern es auch in den Interface Optionen ('Aktionsleisten' Menü) aktiviert ist."
	L["If checked, cooldown icons will be shown above the player frame instead of the target frame.|n|nIf unchecked, cooldown icons will be shown above the target frame."] = "Wenn ausgewählt, werden Abklingzeitsymbole über dem Spielerfenster statt über dem Zielfenster angezeigt.|n|nWenn nicht ausgewählt, werden Abklingzeitsymbole über dem Zielfenster angezeigt."
	L["If checked, damage and healing numbers in the player and pet portrait frames will be hidden."] = "Wenn ausgewählt, werden Schadens und Heilungszahlen am Spieler und Begleiter-Fenster versteckt."
	L["If checked, dragging the General chat tab while the chat frame is locked will expand the chat frame upwards.|n|nIf the chat frame is unlocked, dragging the General chat tab will move the chat frame."] = "Wenn ausgewählt, wird das Chat-Fenster nach oben erweitert wenn es fixiert ist aber am Reiter/Tab gezogen wird.|n|nFalls das Chat-Fenster freigegeben ist, wird es durch das ziehen bewegt."
	L["If checked, drunken messages will be blocked unless they apply to your character.|n|nThis applies to the system channel."] = "Wenn ausgewählt, werden Nachrichten über Betrunkenheit blockiert, sofern sie nicht deinen Charakter betreffen.|n|nDies gilt für den Systemkanal."
	L["If checked, duel requests will be blocked unless the player requesting the duel is a friend."] = "Wenn ausgewählt, werden Duellanfragen blockiert, es sei denn, der Spieler, der dich herausfordert, ist ein Freund."
	L["If checked, duel victory and retreat messages will be blocked unless your character took part in the duel.|n|nThis applies to the system channel."] = "Wenn ausgewählt, werden Nachrichten über Duellsiege und -rückzüge blockiert, sofern dein Charakter nicht am Duell teilgenommen hat.|n|nDies gilt für den Systemkanal."
	L["If checked, emote sounds will be silenced while your character is resting or at the Grim Guzzler.|n|nEmote sounds will be enabled at all other times."] = "Wenn ausgewählt, werden Sprach-Emotes stumm geschaltet, während dein Charakter sich ausruht oder im Grimmigen Säufer ist.|n|nZu allen anderen Zeiten sind Sprach-Emotes aktiviert."
	L["If checked, enemy nameplates will be shown during combat and hidden when combat ends."] = "Wenn ausgewählt, werden feindliche Namensplaketten während dem Kampf angezeigt aber außerhalb des Kampfs versteckt."
	L["If checked, flight times will be shown in the flight map and when you take a flight."] = "Wenn ausgewählt, werden Flugzeiten auf der Flugkarte und während eines Fluges angezeigt."
	L["If checked, footsteps for horse mounts will be muted."] = "Wenn ausgewählt, werden die Schrittgeräusche von Pferdereittieren stummgeschaltet."
	L["If checked, footsteps for mechanical mounts will be muted."] = "Wenn ausgewählt, werden die Schrittgeräusche von mechanischen Reittieren stummgeschaltet."
	L["If checked, group invites will only be sent to friends.|n|nIf unchecked, group invites will be sent to everyone."] = "Wenn ausgewählt, werden Gruppeneinladungen nur an Freunde gesendet.|n|nWenn nicht ausgewählt, werden Gruppeneinladungen an alle gesendet."
	L["If checked, guild ranks will be shown for players in your guild."] = "Wenn ausgewählt, werden Gilden Ränge für Spieler in deiner Gilde angezeigt."
	L["If checked, guild ranks will be shown for players who are not in your guild."] = "Wenn ausgewählt, werden Gildenränge für Spieler angezeigt, die nicht in deiner Gilde sind."
	L["If checked, gyrocopters will be muted.|n|nThis applies to the engineering flying machine mounts."] = "Wenn ausgewählt, werden Gyrocopter stummgeschaltet.|n|nDies betrifft die fliegenden Ingenieursreittiere."
	L["If checked, helm and cloak toggle checkboxes will be shown in the character frame.|n|nYou can hold shift and right-click the checkboxes to switch layouts."] = "Wenn diese Option aktiviert ist, werden im Charakterfenster Kontrollkästchen zum Umschalten von Helm und Umhang angezeigt. |n|nSie können die Umschalttaste gedrückt halten und mit der rechten Maustaste auf die Kontrollkästchen klicken, um die Ansicht zu wechseln."
	L["If checked, holiday event sounds will be muted.|n|nThis applies to Headless Horseman."] = "Wenn ausgewählt, werden Feiertags Event Sounds stumm geschalten.|n|nDas trifft zu für den kopflosen Reiter."
	L["If checked, keybind text will not be shown on action buttons."] = "Wenn ausgewählt, wird der Tastenbelegungstext auf den Aktionsschaltflächen nicht angezeigt."
	L["If checked, login screen sounds will be muted when you logout of the game.|n|nNote that login screen sounds will not be muted when you initially launch the game.|n|nThey will only be muted when you logout of the game.  This includes manually logging out as well as being forcefully logged out by the game server for reasons such as being away for an extended period of time."] = "Wenn ausgewählt, werden die Geräusche des Anmeldebildschirms stummgeschaltet, wenn du dich aus dem Spiel ausloggst.|n|nBeachte, dass die Geräusche des Anmeldebildschirms beim ersten Start des Spiels nicht stummgeschaltet werden.|n|nSie werden nur stummgeschaltet, wenn du dich aus dem Spiel ausloggst.  Dies gilt sowohl für das manuelle Ausloggen als auch für das erzwungene Ausloggen durch den Spielserver, zum Beispiel nach längerer Abwesenheit."
	L["If checked, macro text will not be shown on action buttons."] = "Wenn ausgewählt, wird der Makrotext auf den Aktionsschaltflächen nicht angezeigt."
	L["If checked, mechanostriders will be quieter."] = "Wenn ausgewählt, werden Roboschreiter leiser."
	L["If checked, members of your guild will be treated as friends for all of the options on this page."] = "Wenn ausgewählt, werden Mitglieder deiner Gilde für alle Optionen auf dieser Seite wie Freunde behandelt."
	L["If checked, messages containing spell links will be blocked while you are in combat.|n|nThis is useful for blocking spell interrupt spam.|n|nThis applies to the say, party, raid, emote and yell channels."] = "Wenn ausgewählt, werden Nachrichten mit Zauberlinks blockiert, während du im Kampf bist.|n|nDies ist nützlich, um Spam über Zauberunterbrechungen zu blockieren.|n|nDies gilt für die Kanäle Sagen, Gruppe, Schlachtzug, Emote und Schreien."
	L["If checked, minimap buttons for addons will be collected and placed in a bag which you can toggle by right-clicking the minimap.|n|nThis setting will help you declutter the minimap without the need to install a separate addon to do that."] = "Wenn ausgewählt, werden die Minikartenschaltflächen von Addons gesammelt und in einer Tasche abgelegt, die du per Rechtsklick auf die Minikarte ein- und ausblenden kannst.|n|nDiese Einstellung hilft dir, die Minikarte aufzuräumen, ohne dafür ein separates Addon installieren zu müssen."
	L["If checked, most error messages (such as 'Not enough rage') will not be shown.  Some important errors are excluded.|n|nIf you have the minimap button enabled, you can hold down the alt key and click it to toggle error messages without affecting this setting."] = "Wenn ausgewählt, werden die meisten Fehlermeldungen (wie 'Nicht genug Wut') nicht angezeigt.  Einige wichtige Fehler sind ausgenommen.|n|nWenn die Minikartenschaltfläche aktiviert ist, kannst du die ALT-Taste gedrückt halten und darauf klicken, um Fehlermeldungen umzuschalten, ohne diese Einstellung zu ändern."
	L["If checked, party invitations from friends will be automatically accepted unless you are queued for a battleground or the Looking for Group feature."] = "Wenn ausgewählt, werden Gruppeneinladungen von Freunden automatisch angenommen, es sei denn, du befindest dich in der Warteschlange für ein Schlachtfeld oder die Gruppensuche."
	L["If checked, party invitations will be blocked unless the player inviting you is a friend."] = "Wenn ausgewählt, werden Gruppeneinladungen blockiert, es sei denn, der Spieler, der dich einlädt, ist ein Freund."
	L["If checked, Piccolo of the Flaming Fire wil be muted.|n|nNote that enabling this will also mute the harp sound of the warlock seduction spell."] = "Wenn ausgewählt, wird Pikkolo des Flammenfeuers stummgeschaltet.|n|nBeachte, dass dadurch auch der Harfenklang des Verführungszaubers des Hexenmeisters stummgeschaltet wird."
	L["If checked, quest levels will be shown."] = "Wenn ausgewählt, werden Queststufen angezeigt."
	L["If checked, quests will be selected, accepted and turned-in automatically.|n|nQuests which have a gold requirement will not be turned-in automatically."] = "Wenn ausgewählt, werden Quests automatisch ausgewählt, angenommen und abgegeben.|n|nQuests, die Gold erfordern, werden nicht automatisch abgegeben."
	L["If checked, raid chat will be colored blue (to match the default party chat color)."] = "Wenn ausgewählt, wird der Schlachtzugschat blau eingefärbt (passend zur standardmäßigen Farbe des Gruppenchats)."
	L["If checked, recent chat will be restored when you reload your interface."] = "Wenn ausgewählt, wird der letzte Chatverlauf wiederhergestellt, wenn du dein Interface neu lädst."
	L["If checked, resurrection requests will be accepted automatically."] = "Wenn ausgewählt, werden Wiederbelebungsanfragen automatisch angenommen."
	L["If checked, resurrection requests will not be automatically accepted if the player resurrecting you is in combat."] = "Wenn ausgewählt, werden Wiederbelebungsanfragen nicht automatisch angenommen, wenn sich der Spieler, der dich wiederbelebt, im Kampf befindet."
	L["If checked, Screech will be muted.|n|nThis is a spell used by some flying pets."] = "Wenn ausgewählt, wird Kreischen stummgeschaltet.|n|nDies ist ein Zauber, den einige fliegende Begleiter verwenden."
	L["If checked, shared quests will be declined unless the player sharing the quest is a friend."] = "Wenn ausgewählt, werden geteilte Quests abgelehnt, es sei denn, der Spieler, der die Quest teilt, ist ein Freund."
	L["If checked, spell IDs will be shown in buff icon tooltips located in the buff frame and under the target frame."] = "Wenn ausgewählt, werden Zauber IDs in den Tooltips der Stärkunszauber Leiste und unter dem Ziel-Fenster angezeigt."
	L["If checked, status text will be shown in the druid power bar as long as status text is enabled in the game settings interface display panel."] = "Wenn ausgewählt, wird in der Druidenkraftleiste Statustext angezeigt, sofern der Statustext im Anzeigebereich der Spieleinstellungen aktiviert ist."
	L["If checked, sticky chat will be disabled.|n|nNote that this does not apply to temporary chat windows."] = "Wenn ausgewählt, wird das sticky Chat Verhalten deaktviert.|n|nBeachte, dass dies für temporäre Chat-Fenster nicht funktioniert."
	L["If checked, summon requests will be accepted automatically unless you are in combat."] = "Wenn ausgewählt, werden Beschwörungs-Anfragen standardmäßig akzeptiert sofern du dich nicht im Kampf befindest."
	L["If checked, the addon listing will be shown in alphabetical order without categories."] = "Wenn ausgewählt, wird die Addon-Liste alphabetisch und ohne Kategorien angezeigt."
	L["If checked, the amount of time it takes to auto loot creatures will be significantly reduced."] = "Wenn ausgewählt, wird die benötigte Zeit zum Kreaturen Plündern erheblich verkürzt."
	L["If checked, the button to toggle the raid container frame will be shown just above the raid management frame (left side of the screen) instead of in the raid management frame itself.|n|nThis allows you to toggle the raid container frame without needing to open the raid management frame."] = "Wenn ausgewählt, wird der Button zum Schlachtzugsfenster anzeigen/verstecken oberhalb des Schlachtzugs-Managements Fenster (auf der linken Seite des Bildschirms) angezeigt - statt innerhalb des Menüs.|n|nDas erlaubt das anzeigen/verstecken des Schlachtzugsfenster ohne das Menü öffnen zu müssen."
	L["If checked, the clock will be hidden."] = "Wenn ausgewählt, wird die Uhrzeit versteckt."
	L["If checked, the combat log will be hidden.|n|nThe combat log must be docked in order for this option to work.|n|nIf the combat log is undocked, you can dock it by dragging the tab (and reloading your UI) or by resetting the chat windows (from the chat menu)."] = "Wenn ausgewählt, wird der Kampflog versteckt.|n|nDamit diese Option richtig funktioniert muss der Kampflog fixiert sein.|n|nFalls das Chat-Fenster des Kampflogs freigegeben ist, kannst du es wieder fixieren indem du den Tab/Reiter zurück ziehst oder in dem du vom Chat Menü aus die Chat-Fenster zurücksetzt."
	L["If checked, the day and night indicator will be hidden."] = "Wenn ausgewählt, wird die Tag- und Nachtanzeige versteckt."
	L["If checked, the editbox will be moved to the top of the chat frame."] = "Wenn ausgewählt, wird das Chat-Fenster zum Nachrichten Verfassen am oberen Rand des Chat-Fenster geöffnet."
	L["If checked, the flight progress bar background texture will be shown."] = "Wenn ausgewählt, wird die Hintergrundtextur der Flugfortschrittsleiste angezeigt."
	L["If checked, the flight progress bar background will fill instead of drain."] = "Wenn ausgewählt, füllt sich der Hintergrund der Flugfortschrittsleiste, anstatt sich zu leeren."
	L["If checked, the flight progress bar destination will be shown."] = "Wenn ausgewählt, wird das Ziel auf der Flugfortschrittsleiste angezeigt."
	L["If checked, the grey screen of death and the netherworld effect will be disabled."] = "Wenn ausgewählt, wird der graue Geister Bildschirm Effekt und der Jenseits Effekt deaktiviert."
	L["If checked, the health bar will not be shown."] = "Wenn ausgewählt, wird die Gesundheitsleiste nicht angezeigt."
	L["If checked, the interface button sound, the chat frame tab click sound and the game menu toggle sound will be muted."] = "Wenn ausgewählt, werden der Interface Button Sound, der Chat-Fenster Tab/Reiter Klick Ton und der Spielmenü Öffnungs & Schließungs Sound stumm geschalten."
	L["If checked, the Looking for Group button will be hidden while you are not queued.|n|nThis only applies to game realms with a Looking for Group feature."] = "Wenn ausgewählt, wird die Schaltfläche für die Gruppensuche versteckt, solange du nicht in einer Warteschlange bist.|n|nDies gilt nur für Spielwelten mit einer Gruppensuchfunktion."
	L["If checked, the main bar gryphons will not be shown."] = "Wenn ausgewählt, wird das Greifenpaar von der Haupt-Aktionsleiste nicht angezeigt."
	L["If checked, the minimap shape will be square.|n|nMinimap rotation (a setting in Edit Mode) is not recommended with a square minimap."] = "Wenn ausgewählt, wird die Minikarte eckig dargestellt.|n|nDie Drehung der Minikarte (eine Einstellung im Bearbeitungsmodus) wird bei einer eckigen Minikarte nicht empfohlen."
	L["If checked, the number of free bag slots will be shown in the backpack button icon and tooltip."] = "Wenn diese Option aktiviert ist, wird die Anzahl der freien Gepäckfächer im Symbol für die Rucksackschaltfläche und im Tooltip angezeigt."
	L["If checked, the player frame background will be shown in class color."] = "Wenn ausgewählt, wird der Hintergrund vom Spieler Fenster in Klassenfarbe angezeigt."
	L["If checked, the player frame group indicator and the group labels displayed above the compact raid frames and the pullout raid frames will be hidden."] = "Wenn ausgewählt, werden die Gruppenanzeige im Spielerfenster sowie die Gruppenbeschriftungen über den kompakten Schlachtzugsfenstern und den herausgezogenen Schlachtzugsfenstern versteckt."
	L["If checked, the professions frame will be larger."] = "Wenn diese Option aktiviert ist, wird der Rahmen für Berufe größer."
	L["If checked, the quest difficulty will be shown next to the quest level in the quest log list.|n|nThis will indicate whether the quest requires a group (+), dungeon (D), raid (R) or PvP (P).|n|nThe quest difficulty will always be shown in the quest log detail pane regardless of this setting."] = "Wenn ausgewählt, wird die Questschwierigkeit neben der Queststufe in der Questlogliste angezeigt.|n|nDies zeigt an, ob die Quest eine Gruppe (+), einen Dungeon (D), einen Schlachtzug (R) oder PvP (P) erfordert.|n|nDie Questschwierigkeit wird unabhängig von dieser Einstellung immer im Detailbereich des Questlogs angezeigt."
	L["If checked, the quest log frame will be larger and feature a world map button and quest levels."] = "Wenn diese Option aktiviert ist, ist der Rahmen des Questlogs größer und verfügt über eine Schaltfläche für die Weltkarte und Queststufen."
	L["If checked, the quest log frame will be larger."] = "Wenn ausgewählt, wird das Questlogfenster größer."
	L["If checked, the ready check sound will be muted."] = "Wenn ausgewählt, wird der Ton vom Bereitschaftscheck stumm geschalten."
	L["If checked, the remaining flight time will be spoken using text to speech.|n|nChanges to this setting will take effect on the next flight you take."] = "Wenn ausgewählt, wird die verbleibende Flugzeit per Text-to-Speech angesagt.|n|nÄnderungen an dieser Einstellung werden beim nächsten Flug wirksam."
	L["If checked, the screen glow will be disabled.|n|nEnabling this option will also disable the drunken haze effect."] = "Wenn ausgewählt, wird das Bildschirm leuchten/Schimmer deaktviert.|n|nDurch das Aktivieren der Option wird auch die Betrunkenheits-Trübung deaktiviert."
	L["If checked, the skill trainer frame will be larger and feature a train all skills button."] = "Wenn ausgewählt, wird das Lehrerfenster größer und enthält eine Schaltfläche zum Erlernen aller Fertigkeiten."
	L["If checked, the spell fizzle sounds will be muted."] = "Wenn ausgewählt, werden die fizzle/missglückt Sounds von Zauber stumm geschalten."
	L["If checked, the stance bar will not be shown."] = "Wenn ausgewählt, wird die Haltungsleiste versteckt."
	L["If checked, the target frame background and focus frame background will be shown in class color."] = "Wenn ausgewählt, wird der Hintergrund des Ziel und Fokus Fensters in Klassenfarbe angezeigt."
	L["If checked, the tooltip will be color coded and you will be able to modify the tooltip layout and scale."] = "Wenn ausgewählt, wird der Tooltip farbkodiert und du kannst das Layout sowieso die Größe ändern."
	L["If checked, the tracking button will be hidden while the pointer is not over the minimap."] = "Wenn ausgewählt, wird die Verfolgungsschaltfläche versteckt, solange sich der Mauszeiger nicht über der Minikarte befindet."
	L["If checked, the vendor price will be shown in item tooltips."] = "Wenn diese Option aktiviert ist, wird der Händlerverkaufspreis in den Tooltips angezeigt."
	L["If checked, the zone text bar will be hidden."] = "Wenn ausgewählt, wird die Leiste mit dem Gebietsnamen versteckt."
	L["If checked, the zoom buttons will be hidden.  You can use the mousewheel to zoom regardless of this setting."] = "Wenn ausgewählt, werden die Zoom Buttons versteckt. Das Mausrad kann weiterhin zum Zoomen verwendet werden."
	L["If checked, tooltips for world units will be hidden during combat."] = "Wenn ausgewählt, werden Tooltips für Einheiten in der Spielwelt im Kampf versteckt."
	L["If checked, train sounds will be muted."] = "Wenn ausgewählt, werden Töne von Bahnen stumm geschalten."
	L["If checked, unit targets will be shown."] = "Wenn ausgewählt, werden die Ziele der Einheit angezeigt."
	L["If checked, when you change the audio output device in your operating system, the game audio output device will change automatically as long as a cinematic is not playing at the time.|n|nFor this to work, the game audio output device will be set to system default."] = "Wenn ausgewählt, wechselt das Audioausgabegerät des Spiels automatisch, wenn du das Audioausgabegerät in deinem Betriebssystem änderst, sofern gerade keine Videosequenz abgespielt wird.|n|nDamit dies funktioniert, wird das Audioausgabegerät des Spiels auf den Systemstandard gesetzt."
	L["If checked, Wowhead links will be shown above the quest log frame."] = "Wenn diese Option aktiviert ist, werden Wowhead-Links über dem Questprotokollrahmen angezeigt."
	L["If checked, Wowhead links will go directly to the comments section."] = "Wenn ausgewählt, führen Wowhead-Links direkt zum Kommentarbereich."
	L["If checked, yawns from hunter pet cats will be muted."] = "Wenn ausgewählt, wird das Gähnen von Katzen als Jägerbegleiter stummgeschaltet."
	L["If checked, you can block drunken spam and duel spam."] = "Wenn ausgewählt, kannst du Betrunkenen-Spam und Duell-Spam blockieren."
	L["If checked, you can hold down the alt key while opening a gossip window to automatically select a single gossip item.|n|nIf the gossip item type is banker, taxi, trainer, vendor or battlemaster, gossip will be skipped without needing to hold the alt key.  You can hold the shift key down to prevent this."] = "Wenn ausgewählt, kannst du beim Öffnen eines Gesprächsfensters die ALT-Taste gedrückt halten, um automatisch eine einzelne Gesprächsoption auszuwählen.|n|nWenn es sich bei der Gesprächsoption um einen Bankier, Flugmeister, Lehrer, Händler oder Kampfmeister handelt, wird das Gespräch übersprungen, ohne dass du die ALT-Taste gedrückt halten musst.  Halte die Umschalttaste gedrückt, um dies zu verhindern."
	L["If checked, you can hold down the control key and click a chat tab to view recent chat in a copy-friendly window."] = "Wenn ausgewählt, kannst du per STRG-Klick auf den Chat Reiter/Tab ein Fenster öffnen um kürzliche Nachrichten einfach zu kopieren."
	L["If checked, you can hold shift while tooltips are hidden to show them temporarily."] = "Wenn ausgewählt, kannst du die Umschalttaste gedrückt halten, während Tooltips versteckt sind, um sie vorübergehend anzuzeigen."
	L["If checked, you can press the arrow keys to move the insertion point left and right in the chat frame.|n|nIf unchecked, the arrow keys will use the default keybind setting."] = "Wenn ausgewählt, können die Pfeiltasten im Chat verwendet werden um den Cursor nach links oder rechts zu bewegen.|n|nWenn nicht ausgewählt, werden die Pfeiltasten die Standard Tastenbelegung verwenden."
	L["If checked, you can specify an edit mode layout that will always be applied when you login to any character."] = "Wenn ausgewählt, kannst du ein Bearbeitungsmoduslayout festlegen, das immer angewendet wird, wenn du dich mit einem beliebigen Charakter einloggst."
	L["If checked, you will be able to cancel cinematics without being prompted for confirmation."] = "Wenn ausgewählt, kannst du Cinematics ohne Bestätigung abbrechen."
	L["If checked, you will be able to change the font size of book text."] = "Wenn diese Option aktiviert ist, können Sie die Schriftgröße des Buchtexts ändern."
	L["If checked, you will be able to change the font size of quest text."] = "Wenn ausgewählt, kannst du die Quest Text Schriftgröße ändern."
	L["If checked, you will be able to change the font size of standard mail text.|n|nThis does not affect mail created using templates (such as auction house invoices)."] = "Wenn ausgewählt, kannst du die Standard Schriftgröße von Brieftexten ändern.|n|nDas funktioniert nicht für Briefe die aus einer Vorlage erstellt wurden (sowie Auktionshaus Briefe)."
	L["If checked, you will be able to change the position and scale of the timer bar.|n|nThe timer bar is used for showing remaining breath when underwater as well as other things."] = "Wenn ausgewählt, kannst du die Position und Größe der Timerleiste ändern.|n|nDie Timerleiste wird unter anderem verwendet, um den verbleibenden Atem unter Wasser anzuzeigen."
	L["If checked, you will be able to change the position and scale of the widget frame.|n|nThe widget frame is commonly used for showing PvP scores and tracking objectives."] = "Wenn ausgewählt, kannst du die Position und Größe des Widget-Rahmen ändern.|n|nDer Widget-Rahmen wird für gewöhnlich benutzt um den PvP Punktestand und Ziele zu verfolgen."
	L["If checked, you will be able to customise the flight map."] = "Wenn ausgewählt, kannst du die Flugkarte anpassen."
	L["If checked, you will be able to customise the minimap."] = "Wenn ausgewählt, kannst du die Minimap anpassen."
	L["If checked, you will be able to drag the chat frame to the edge of the screen."] = "Wenn ausgewählt, kannst du das Chat-Fenster bis zum Rand des Bildschirms verschieben."
	L["If checked, you will be able to mute a selection of game sounds."] = "Wenn ausgewählt, kannst du eine Auswahl an Spielsounds stummschalten."
	L["If checked, you will be able to mute a selection of mount sounds."] = "Wenn ausgewählt, kannst du eine Auswahl von Reittiergeräuschen stummschalten."
	L["If checked, you will be able to mute your own choice of sounds."] = "Wenn ausgewählt, kannst du Sounds deiner Wahl stummschalten."
	L["If checked, you will be able to pan (right-button) and zoom (mousewheel) in the character frame, dressup frame and inspect frame.|n|nA toggle stats button will be shown in the character frame.  You can also middle-click the character model to toggle stats.|n|nModel rotation controls will be hidden.  Buttons to toggle gear will be added to the dressup frame."] = "Wenn ausgewählt, kannst du im Charakterfenster, in der Anprobe und im Betrachtungsfenster schwenken (rechte Maustaste) und zoomen (Mausrad).|n|nIm Charakterfenster wird eine Schaltfläche zum Umschalten der Werte angezeigt.  Du kannst auch mit der mittleren Maustaste auf das Charaktermodell klicken, um die Werte umzuschalten.|n|nDie Steuerelemente zum Drehen des Modells werden versteckt.  Der Anprobe werden Schaltflächen zum Umschalten der Ausrüstung hinzugefügt."
	L["If checked, you will be able to place up to five beneficial cooldown icons above the target frame."] = "Wenn ausgewählt, kannst du bis zu 5 positive Abklingzeiteiten über dem Ziel-Fenster anzeigen."
	L["If checked, you will be able to set some additional rules for when your character is automatically dismounted."] = "Wenn ausgewählt, kannst du einige zusätzliche Regeln festlegen, wann dein Charakter automatisch abgesetzt wird."
	L["If checked, you will be able to set the density of weather effects."] = "Wenn ausgewählt, kannst du die Intensität der Wetter Effekte bestimmen."
	L["If checked, you will be able to show a rare, elite or rare elite chain around the player frame."] = "Wenn ausgewählt, kannst du dein Spieler Portrait mit einem Rare, Elite oder Rare Elite Rahmen dekorieren."
	L["If checked, you will be able to show customisable borders around the edges of the screen.|n|nThe borders are placed on top of the game world but under the UI so you can place UI elements over them."] = "Wenn ausgewählt, kannst du flexible Ränder um die Ecken des Bildschirms zeigen.|n|nDie Ränder werden über der Spielwelt aber unter der Benutzeroberfläche angezeigt. Somit können UI Elemente darüber plaziert werden."
	L["If checked, you will be able to zoom out to a greater distance."] = "Wenn ausgewählt, kannst du auf weitere Distanz herauszoomen."
	L["If checked, you will be dismounted when you attempt to cast a non-instant cast spell while moving."] = "Wenn ausgewählt, wirst du abgesetzt, wenn du versuchst, während der Bewegung einen Zauber ohne Spontanwirkung zu wirken."
	L["If checked, you will be dismounted when you attempt to cast a spell but don't have the rage, mana or energy to cast it."] = "Wenn ausgewählt, wirst du abgesetzt, wenn du versuchst, einen Zauber zu wirken, aber nicht genug Wut, Mana oder Energie dafür hast."
	L["If checked, you will be dismounted when you instruct a flight master to open the flight map."] = "Wenn ausgewählt, wirst du abgesetzt, wenn du einen Flugmeister anweist, die Flugkarte zu öffnen."
	L["If checked, you will be prompted to submit missing flight times."] = "Wenn ausgewählt, wirst du aufgefordert, fehlende Flugzeiten einzureichen."
	L["If checked, you will need to hold the override key down for quests to be automated.|n|nIf unchecked, holding the override key will prevent quests from being automated."] = "Wenn ausgewählt, musst du die Überschreibungstaste gedrückt halten, damit Quests automatisiert werden.|n|nWenn nicht ausgewählt, verhindert das Gedrückthalten der Überschreibungstaste die Automatisierung von Quests."
	L["If checked, you will no longer need to type delete when destroying a superior quality item.|n|nIn addition, item links will be shown in all item destroy confirmation windows."] = "Wenn ausgewählt, musst du nicht mehr löschen schreiben sofern du einen Gegenstand mit Überragendender Qualität zerstören möchtest.|n|nZusätzlich werden Gegenstands Verlinkungen in allen Zerstörungs-Bestätigungs Fenster angezeigt."
	L["If checked, you will not release automatically in Alterac Valley."] = "Wenn ausgewählt, wird dein Geist im Alteractal nicht automatisch freigelassen."
	L["If checked, you will release automatically after you die in a battleground.|n|nYou will not release automatically if you have the ability to self-resurrect."] = "Wenn ausgewählt, wird der Geist automatisch freigelassen falls du in einem Schlachtfeld stirbst.|n|nDer Geist wird nicht automatisch freigelassen, wenn du dich selbst wiederbeleben kannst."
	L["If checked, your bags will not be opened or closed automatically when you interact with a merchant, bank or mailbox."] = "Wenn ausgewählt, werden die Taschen nicht automatisch geöffnet oder geschlossen wenn du mit einem Händler, Bank oder einem Briefkasten interagierst."
	L["If checked, your chat history will increase to 4096 lines.  If unchecked, the default will be used (128 lines).|n|nEnabling this option may prevent some chat text from showing during login."] = "Wenn ausgewählt, wird der Chat Verlauf auf 4096 Zeilen erweitert. Wenn nicht ausgewählt, wird der Standard von 128 Zeilen benutzt.|n|nDas Aktivieren der Option wird möglicherweise die Anzeige von Chat Text während dem Login verhindern."
	L["If checked, your gear will be repaired automatically when you visit a suitable merchant.|n|nYou can hold the shift key down when you talk to a merchant to override this setting."] = "Wenn du einen passenden Händler aufsuchst wird deine Rüstung automatisch repariert, falls aktiviert.|n|nWenn, während der Händler angesprochen wird, die Shift Taste gedrückt gehalten wird, kann diese Einstellung überschrieben werden."
	L["If checked, zone text will not be shown (eg. 'Ironforge')."] = "Gebietstext (z.B, 'Eisenschmiede') wird nicht angezeigt, falls ausgewählt."
	L["If the edit mode layout name that you enter here exists, that layout will be applied when you login to any character on your account."] = "Wenn der hier eingegebene Name eines Bearbeitungsmoduslayouts existiert, wird dieses Layout angewendet, wenn du dich mit einem beliebigen Charakter deines Accounts einloggst."
	L["If you use the 'Hide addon buttons' or 'Minimap button bag' settings but you want some addon buttons to remain visible around the minimap, enter the button names into the editbox below separated by commas.|n|nChanges will require a UI reload to take effect."] = "Wenn du die Einstellungen 'Addon-Schaltflächen verstecken' oder 'Minikartenschaltflächen-Tasche' verwendest, aber einige Addon-Schaltflächen um die Minikarte herum sichtbar bleiben sollen, gib die Namen der Schaltflächen durch Kommas getrennt in das Eingabefeld unten ein.|n|nÄnderungen erfordern ein Neuladen des UI, um wirksam zu werden."
	L["If you want to listen to a sound file, enter the sound file ID into the editbox and click the play button.|n|nYou can scroll the mousewheel over the editbox to play neighbouring sound files."] = "Wenn du eine Sounddatei anhören möchtest, gib die Sounddatei-ID in das Eingabefeld ein und klicke auf die Abspielen-Schaltfläche.|n|nDu kannst das Mausrad über dem Eingabefeld drehen, um benachbarte Sounddateien abzuspielen."
