	L["Leatrix Plus needs to be updated with the flight details.  Press CTRL/C to copy the flight details below then paste them into an email to flight@leatrix.com.  When your report is received, Leatrix Plus will be updated and you will never see this window again for this flight."] = "Leatrix Plus muss mit den Flugdetails aktualisiert werden.  Drücke STRG/C, um die unten stehenden Flugdetails zu kopieren, und füge sie dann in eine E-Mail an flight@leatrix.com ein.  Sobald dein Bericht eingegangen ist, wird Leatrix Plus aktualisiert und du wirst dieses Fenster für diesen Flug nie wieder sehen."
	L["Leatrix Plus will not overwrite LeaPlusDB at next logout."] = "Beim nächsten Logout wird LeaPlusDB nicht durch Leatrix Plus überschrieben."
