	L["Click to set the sound file limit.  Use the mousewheel on the editbox along with the step buttons below to adjust the sound limit.  Acceptable range is from 1 to 9000000.  Sound files higher than this limit will be muted."] = "Cliquez pour définir la limite des fichiers sonores.  Utilisez la molette de la souris sur la zone de saisie ainsi que les boutons de pas ci-dessous pour ajuster la limite.  La plage acceptée va de 1 à 9000000.  Les fichiers sonores au-delà de cette limite seront rendus muets."
