	L["Drag to set the size of the top border."] = "Trascina per impostare la dimensione del bordo superiore."
	L["Drag to set the square minimap border width."] = "Trascina per impostare la larghezza del bordo della minimappa quadrata."
	L["Drag to set the square minimap size.|n|nAdjusting this slider makes the minimap bigger but keeps the elements the same size."] = "Trascina per impostare la dimensione della minimappa quadrata.|n|nRegolare questo cursore ingrandisce la minimappa ma mantiene gli elementi della stessa dimensione."
