	L["Click to reset the settings on this page."] = "Clique para redefinir as configurações nesta página."
	L["Click to return to the main menu."] = "Clique para retornar ao menu principal."
	L["Click to set the sound file limit.  Use the mousewheel on the editbox along with the step buttons below to adjust the sound limit.  Acceptable range is from 1 to 9000000.  Sound files higher than this limit will be muted."] = "Clique para definir o limite de arquivos de som.  Use a roda do mouse na caixa de texto junto com os botões de incremento abaixo para ajustar o limite.  O intervalo aceito é de 1 a 9000000.  Arquivos de som acima desse limite serão silenciados."
	L["Click to toggle the addon buttons editor."] = "Clique para alternar o editor de botões do addon."
	L["Click to toggle the frame alignment grid."] = "Clique para alternar a grade de alinhamento do quadro."
	L["Click to unmute every sound in the game."] = "Clique para reativar todos os sons do jogo."
	L["Click to unmute sounds in the list."] = "Clique para ativar os sons na lista."
