	L["Enter item IDs separated by commas.  Item IDs can be found in item tooltips while this panel is showing.|n|nJunk items entered here will not be sold automatically.|n|nWhite items entered here will be sold automatically.|n|nThe editbox tooltip will show you more information about the items you have entered."] = "Введите ID предметов, разделенные запятыми. ID предметов можно найти во всплывающей подсказке предметов во время отображения этой панели.|n|nХлам, введенный здесь, не будет продаваться автоматически.|n|nБелые предметы, введенные здесь, будут продаваться автоматически.|n|nВсплывающая подсказка окна редактирования, покажет вам более подробную информацию о введенных вами предметах."
	L["Enter sound file IDs separated by comma then click the Mute button.|n|nIf you wish, you can enter a brief note for each file ID but do not include numbers in your notes.|n|nFor example, you can enter 'DevAura 569679, RetAura 568744' to mute the Devotion Aura and Retribution Aura spells.|n|nUse Leatrix Sounds to find, test and play sound file IDs."] = "Введите идентификаторы звуковых файлов через запятую и нажмите кнопку Заглушить.|n|nПри желании вы можете ввести краткое примечание к каждому идентификатору файла, но не включайте в примечания цифры.|n|nНапример, вы можете ввести 'DevAura 569679, RetAura 568744', чтобы отключить заклинания Devotion Aura и Retribution Aura.|n|nИспользуйте Leatrix Sounds для поиска, тестирования и воспроизведения идентификаторов звуковых файлов."
	L["Enter the spell IDs for the cooldown icons that you want to see.|n|nIf a cooldown icon normally appears under the pet frame, check the pet checkbox.|n|nCooldown icons are saved to your class."] = "Введите ID заклинаний, иконки которых хотите видеть.|n|nЕсли значок перезарядки появляется под рамкой питомца, то нажмите галочку.|n|nИконки восстановления сохраняются для вашего класса."
	L["enter zone or track name"] = "введите название зоны или трека"
