	L["Drag the frame overlay to position the frame."] = "드래그하여 프레임 위치를 조정하세요."
	L["Drag the frame overlay with the left button to position it freely or with the right button to position it using snap-to-grid."] = "왼쪽 버튼으로 프레임을 드래그하여 자유롭게 위치시키거나, 오른쪽 버튼을 사용하여 격자에 맞춰 위치를 조정할 수 있습니다."
	L["Drag to set the cursor X offset."] = "드래그하여 커서 X 위치를 설정하세요."
