	L["If checked, a bag search box will be shown in the backpack frame and the bank frame."] = "가방과 은행 창에 가방 검색란이 표시됩니다."
	L["If checked, a button will be added to the character frame which will show your equipped item durability when you hover the pointer over it.|n|nIn addition, an overall percentage will be shown in the chat frame when you die."] = "캐릭터 창에 버튼이 추가되어 커서를 올려놓으면 장착한 아이템의 내구도를 표시합니다.|n|n또한, 사망 시 채팅창에 전체 내구도 비율이 표시됩니다."
	L["If checked, a cancel form button will be shown on the flight map while you are playing as a shapeshifted druid or shaman."] = "변신한 드루이드나 주술사로 플레이하는 동안 비행 지도에 취소 버튼이 표시됩니다."
	L["If checked, a group invite will be sent to anyone who whispers you with a set keyword as long as you are ungrouped, group leader or raid assistant and not queued for a battleground or the Looking for Group feature.|n|nFriends who message the keyword using Battle.net will not be sent a group invite if they are appearing offline.  They need to either change their online status or use character whispers."] = "파티에 속하지 않은 상태이거나 파티장 또는 부공격대장 역할이며 전장 대기열이나 파티 찾기 기능에 등록되지 않은 경우, 설정된 단어로 귓속말 메시지를 보낸 모든 사람을 초대 합니다.|n|nBattle.net을 통해 메시지를 보낸 친구가 오프라인 상태로 표시될 경우 초대 되지 않습니다. 해당 친구는 온라인 상태로 변경하거나 캐릭터 귓속말 기능을 사용해야 합니다."
	L["If checked, a master volume slider will be shown in the character frame."] = "주 음량 슬라이더가 캐릭터 창에 표시됩니다."
	L["If checked, a minimap button will be available.|n|nClick - Toggle options panel.|n|nSHIFT-click - Toggle music.|n|nALT-click - Toggle errors (if enabled).|n|nCTRL/SHIFT-click - Toggle windowed mode.|n|nCTRL/ALT-click - Toggle Zygor (if installed)."] = "미니맵 버튼이 활성화됩니다.|n|n클릭 - 옵션 창 표시/숨김|n|nSHIFT+클릭 - 음악 재생/중지|n|nALT+클릭 - 오류 메시지 표시/숨김 (활성화된 경우)|n|nCTRL/SHIFT+클릭 - 창 모드 전환|n|nCTRL/ALT+클릭 - Zygor (설치된 경우) 전환"
	L["If checked, a power bar will be shown in the player frame when you are playing a shapeshifted druid."] = "변신한 드루이드로 플레이할 때 플레이어 프레임에 자원바가 표시됩니다."
	L["If checked, a repair summary will be shown in chat when your gear is automatically repaired."] = "장비가 자동으로 수리되면 수리 내역이 채팅창에 표시됩니다."
	L["If checked, a timer will be shown under the PvP encounter ready frame so that you know how long you have left to click the enter button."] = "PvP 입장 프레임 아래에 타이머가 표시되어, 입장 버튼을 클릭할 수 있는 시간이 얼마나 남았는지 알 수 있습니다."
	L["If checked, a train all skills button will be shown in the skill trainer frame allowing you to train all available skills instantly."] = "모든 스킬 배우기 버튼이 NPC 창에 표시되어 사용 가능한 모든 스킬을 즉시 배울 수 있습니다."
	L["If checked, a vendor summary will be shown in chat when junk is automatically sold."] = "자동 판매 시 잡동사니 판매 내역이 채팅창에 표시됩니다."
	L["If checked, A'dal in Shattrath City will be muted."] = "샤트라스의 아달이 음소거됩니다."
	L["If checked, additional font sizes will be available in the chat frame font size menu."] = "채팅창 글꼴 크기 메뉴에서 추가 글꼴 크기를 사용할 수 있습니다."
	L["If checked, additional functionality will be added to the auction house.|n|nBuyout only - create buyout auctions without filling in the starting price.|n|nGold only - set the copper and silver prices at 99 to speed up new auctions.|n|nFind item - search the auction house for the item you are selling.|n|nIn addition, the auction duration setting will be saved account-wide."] = "경매장에 기능이 추가됩니다.|n|n구입 - 시작 가격 입력 없이 구입 경매 생성.|n|n골드 - 신규 경매 속도 향상을 위해 실버/코퍼 가격을 99로 설정.|n|n아이템 찾기 - 판매 중인 아이템을 경매장에서 검색.|n|n또한 경매 기간 설정이 계정 전체에 저장됩니다."
	L["If checked, addon buttons will be hidden while the pointer is not over the minimap."] = "커서가 미니맵 위에 있지 않을 때 애드온 버튼이 숨겨집니다."
	L["If checked, all grey items in your bags will be sold automatically when you visit a merchant.|n|nYou can hold the shift key down when you talk to a merchant to override this setting."] = "가방에 있는 모든 잡동사니 아이템은 상인을 방문할 때 자동으로 판매됩니다.|n|n상인과 대화할 때 shift 키를 누르고 있으면 이 설정을 무시할 수 있습니다."
	L["If checked, an animation slider will be shown in the dressing room."] = "의상실에 애니메이션 슬라이더가 표시됩니다."
	L["If checked, available quests will be accepted automatically."] = "사용 가능한 퀘스트는 자동으로 수락됩니다."
	L["If checked, BattleTag and Real ID friend requests will be automatically declined.|n|nEnabling this option will automatically decline any pending requests."] = "BattleTag 및 실명 ID 친구 요청은 자동으로 거절됩니다.|n|n이 옵션을 활성화하면 대기 중인 모든 요청이 자동으로 거절됩니다."
	L["If checked, chat frame buttons will be hidden.|n|nClicking chat tabs will automatically show the latest messages.|n|nUse the mouse wheel to scroll through the chat history.  Hold down SHIFT for page jump or CTRL to jump to the top or bottom of the chat history."] = "채팅창 버튼이 숨겨집니다.|n|n채팅 탭을 클릭하면 최신 메시지가 자동으로 표시됩니다.|n|n마우스 휠을 사용하여 채팅 기록을 스크롤할 수 있습니다. SHIFT 키를 누른 상태에서 페이지 이동하거나 CTRL 키를 눌러 채팅 기록의 맨 위 또는 맨 아래로 이동할 수 있습니다."
	L["If checked, chat text will not fade out after a time period."] = "채팅 텍스트가 일정 시간이 지나도 사라지지 않습니다."
	L["If checked, class coloring will be used in the player frame and target frame."] = "플레이어 프레임과 대상 프레임에서 직업 색상이 사용됩니다."
	L["If checked, class colors will be used in the chat frame."] = "채팅창에 직업 색상이 사용됩니다."
	L["If checked, clock hourly chimes will be muted."] = "시각마다 울리는 종소리는 음소거됩니다."
	L["If checked, completed quests will be turned-in automatically."] = "완료된 퀘스트는 자동으로 처리됩니다."
	L["If checked, confirmations will no longer appear when you choose a loot roll option or attempt to sell or mail a tradable item."] = "전리품 굴리기 옵션을 선택하거나 거래 가능한 아이템을 판매 또는 우편으로 보내려고 할 때 더 이상 확인 메시지가 나타나지 않습니다."
	L["If checked, cooldown duration numbers will not be shown over the cooldowns.|n|nIf unchecked, cooldown duration numbers will be shown over the cooldowns if they are enabled in the game options panel ('ActionBars' menu)."] = "재사용 대기 시간 숫자는 표시되지 않습니다.|n|n체크 해제 시, 게임 설정(‘행동 단축바’ 메뉴)에서 활성화된 경우 재사용 대기 시간 숫자가 표시됩니다."
	L["If checked, cooldown icons will be shown above the player frame instead of the target frame.|n|nIf unchecked, cooldown icons will be shown above the target frame."] = "재사용 대기 중인 아이콘은 대상 프레임 대신 플레이어 프레임 위에 표시됩니다.|n|n체크 해제 시, 재사용 대기 중인 아이콘은 대상 프레임 위에 표시됩니다."
	L["If checked, damage and healing numbers in the player and pet portrait frames will be hidden."] = "플레이어와 애완동물 초상화 프레임에 표시되는 데미지와 치유 수치가 숨겨집니다."
	L["If checked, dragging the General chat tab while the chat frame is locked will expand the chat frame upwards.|n|nIf the chat frame is unlocked, dragging the General chat tab will move the chat frame."] = "채팅창이 잠겨 있는 동안 일반 채팅 탭을 끌면 채팅창이 위쪽으로 확장됩니다.|n|n채팅창이 잠금 해제되어 있는 경우 일반 채팅 탭을 끌면 채팅창이 이동합니다."
	L["If checked, drunken messages will be blocked unless they apply to your character.|n|nThis applies to the system channel."] = "술 취한 메시지는 캐릭터에 적용되지 않는 한 차단됩니다.|n|n이는 시스템 채널에 적용됩니다."
	L["If checked, duel requests will be blocked unless the player requesting the duel is a friend."] = "결투 신청은 결투를 요청한 플레이어가 친구가 아닌 이상 차단됩니다."
	L["If checked, duel victory and retreat messages will be blocked unless your character took part in the duel.|n|nThis applies to the system channel."] = "결투 승리 및 도망 메시지는 캐릭터가 결투에 참여하지 않는 한 차단됩니다.|n|n이는 시스템 채널에 적용됩니다."
	L["If checked, emote sounds will be silenced while your character is resting or at the Grim Guzzler.|n|nEmote sounds will be enabled at all other times."] = "캐릭터가 휴식 중이거나 험상궂은 주정뱅이 선술집에 있을 때는 감정 표현 소리가 음소거됩니다.|n|n그 외 모든 상황에서는 감정 표현 소리가 활성화됩니다."
	L["If checked, enemy nameplates will be shown during combat and hidden when combat ends."] = "적의 이름표는 전투 중 표시되며, 전투 종료 시 숨겨집니다."
	L["If checked, flight times will be shown in the flight map and when you take a flight."] = "비행 시간은 비행 지도와 비행기 탑승 시 표시됩니다."
	L["If checked, footsteps for horse mounts will be muted."] = "말을 탈 때 나는 발소리가 음소거됩니다."
	L["If checked, footsteps for mechanical mounts will be muted."] = "기계 탈것의 발소리가 음소거됩니다."
	L["If checked, group invites will only be sent to friends.|n|nIf unchecked, group invites will be sent to everyone."] = "파티 초대는 친구에게만 전송됩니다.|n|n선택하지 않으면 파티 초대가 모든 사람에게 전송됩니다."
	L["If checked, guild ranks will be shown for players in your guild."] = "길드원에게는 길드 내 플레이어의 길드 등급이 표시됩니다."
	L["If checked, guild ranks will be shown for players who are not in your guild."] = "동일한 길드에 속하지 않은 플레이어의 길드 등급이 표시됩니다."
	L["If checked, gyrocopters will be muted.|n|nThis applies to the engineering flying machine mounts."] = "자이로콥터의 소리는 꺼집니다.|n|n이것은 기계 비행 탈것에 적용됩니다."
	L["If checked, helm and cloak toggle checkboxes will be shown in the character frame.|n|nYou can hold shift and right-click the checkboxes to switch layouts."] = "머리와 망토 전환 체크박스가 캐릭터 프레임에 표시됩니다.|n|nShift 키를 누른 상태에서 체크박스를 마우스 오른쪽 버튼으로 클릭하면 위치를 조절할 수 있습니다."
	L["If checked, holiday event sounds will be muted.|n|nThis applies to Headless Horseman."] = "주간 이벤트 소리가 음소거됩니다.|n|n이것은 저주받은 기사에게 적용됩니다."
	L["If checked, keybind text will not be shown on action buttons."] = "단축키 텍스트는 버튼에 표시되지 않습니다."
	L["If checked, login screen sounds will be muted when you logout of the game.|n|nNote that login screen sounds will not be muted when you initially launch the game.|n|nThey will only be muted when you logout of the game.  This includes manually logging out as well as being forcefully logged out by the game server for reasons such as being away for an extended period of time."] = "게임에서 로그아웃할 때 로그인 화면 소리가 음소거됩니다.|n|n게임을 처음 실행할 때는 로그인 화면 소리가 음소거되지 않습니다.|n|n게임에서 로그아웃할 때만 음소거됩니다. 여기에는 수동 로그아웃은 물론, 장시간 접속하지 않은 경우 등 게임 서버에 의해 강제 로그아웃되는 경우도 포함됩니다."
	L["If checked, macro text will not be shown on action buttons."] = "매크로 텍스트는 버튼에 표시되지 않습니다."
	L["If checked, mechanostriders will be quieter."] = "기계타조는 더 조용할 것이다."
	L["If checked, members of your guild will be treated as friends for all of the options on this page."] = "귀하의 길드원들은 이 페이지의 모든 옵션에서 친구로 간주됩니다."
	L["If checked, messages containing spell links will be blocked while you are in combat.|n|nThis is useful for blocking spell interrupt spam.|n|nThis applies to the say, party, raid, emote and yell channels."] = "전투 중일 때 주문 링크가 포함된 메시지는 차단됩니다.|n|n이는 주문 방해 알림을 차단하는 데 유용합니다.|n|n이 기능은 일반, 파티, 공격대, 감정, 외침 채널에 적용됩니다."
	L["If checked, minimap buttons for addons will be collected and placed in a bag which you can toggle by right-clicking the minimap.|n|nThis setting will help you declutter the minimap without the need to install a separate addon to do that."] = "애드온용 미니맵 버튼들은 하나의 그룹으로 묶여 미니맵을 마우스 오른쪽 버튼으로 클릭하면 표시 여부를 전환할 수 있는 메뉴에 배치됩니다.|n|n이 설정을 사용하면 별도의 애드온을 설치하지 않고도 미니맵을 깔끔하게 정리할 수 있습니다."
	L["If checked, most error messages (such as 'Not enough rage') will not be shown.  Some important errors are excluded.|n|nIf you have the minimap button enabled, you can hold down the alt key and click it to toggle error messages without affecting this setting."] = "대부분의 오류 메시지 (‘분노 부족’ 등)는 표시되지 않습니다. 일부 중요한 오류는 제외됩니다.|n|n미니맵 버튼이 활성화된 경우, Alt 키를 누른 상태에서 해당 버튼을 클릭하면 이 설정에 영향을 주지 않고 오류 메시지 표시를 전환할 수 있습니다."
	L["If checked, party invitations from friends will be automatically accepted unless you are queued for a battleground or the Looking for Group feature."] = "전장 대기열에 있거나 파티 찾기 기능을 사용 중인 경우를 제외하고, 친구의 파티 초대는 자동으로 수락됩니다."
	L["If checked, party invitations will be blocked unless the player inviting you is a friend."] = "초대하는 플레이어가 친구가 아닌 경우 파티 초대가 차단됩니다."
	L["If checked, Piccolo of the Flaming Fire wil be muted.|n|nNote that enabling this will also mute the harp sound of the warlock seduction spell."] = "춤추는 불꽃 피리 소리가 음소거됩니다.|n|n이 기능을 활성화하면 흑마의 유혹 주문에서 나는 하프 소리도 함께 음소거된다는 점에 유의하십시오."
	L["If checked, quest levels will be shown."] = "퀘스트 레벨이 표시됩니다."
	L["If checked, quests will be selected, accepted and turned-in automatically.|n|nQuests which have a gold requirement will not be turned-in automatically."] = "퀘스트는 자동으로 선택, 수락 및 완료됩니다.|n|n골드 요구 사항이 있는 퀘스트는 자동으로 완료 처리되지 않습니다."
	L["If checked, raid chat will be colored blue (to match the default party chat color)."] = "공격대 채팅은 파란색으로 표시됩니다 (기본 파티 채팅 색상과 동일하게)."
	L["If checked, recent chat will be restored when you reload your interface."] = "UI를 재시작하면 최근 채팅 기록이 복원됩니다."
	L["If checked, resurrection requests will be accepted automatically."] = "부활 요청은 자동으로 수락됩니다."
	L["If checked, resurrection requests will not be automatically accepted if the player resurrecting you is in combat."] = "부활을 요청한 플레이어가 전투 중일 경우, 부활 요청은 자동으로 수락되지 않습니다."
	L["If checked, Screech will be muted.|n|nThis is a spell used by some flying pets."] = "비명 소리가 음소거됩니다.|n|n일부 비행형 애완동물이 사용하는 주문입니다."
	L["If checked, shared quests will be declined unless the player sharing the quest is a friend."] = "퀘스트를 공유하는 플레이어가 친구가 아닌 이상, 공유된 퀘스트는 거부됩니다."
	L["If checked, spell IDs will be shown in buff icon tooltips located in the buff frame and under the target frame."] = "주문 ID는 버프 프레임과 대상 프레임 아래에 있는 버프 아이콘 툴팁에 표시됩니다."
	L["If checked, status text will be shown in the druid power bar as long as status text is enabled in the game settings interface display panel."] = "상태 텍스트는 게임 설정에서 상태 숫자가 활성화된 상태일 때 드루이드 자원바에 표시됩니다."
	L["If checked, sticky chat will be disabled.|n|nNote that this does not apply to temporary chat windows."] = "채팅창 고정 기능이 비활성화됩니다.|n|n단, 임시 채팅창에는 적용되지 않습니다."
	L["If checked, summon requests will be accepted automatically unless you are in combat."] = "전투 중이 아닌 이상 소환 요청은 자동으로 수락됩니다."
	L["If checked, the addon listing will be shown in alphabetical order without categories."] = "애드온 목록을 분류 없이 알파벳순으로 표시합니다."
	L["If checked, the amount of time it takes to auto loot creatures will be significantly reduced."] = "자동 전리품 획득 시간이 크게 단축됩니다."
	L["If checked, the button to toggle the raid container frame will be shown just above the raid management frame (left side of the screen) instead of in the raid management frame itself.|n|nThis allows you to toggle the raid container frame without needing to open the raid management frame."] = "공격대 프레임 전환 버튼은 이제 공격대 관리 프레임 내부 (화면 왼쪽)가 아닌, 공격대 관리 프레임 바로 위에 표시됩니다.|n|n이를 통해 공격대 관리 프레임을 열지 않고도 공격대 프레임을 전환할 수 있습니다."
	L["If checked, the clock will be hidden."] = "시계를 숨깁니다."
	L["If checked, the combat log will be hidden.|n|nThe combat log must be docked in order for this option to work.|n|nIf the combat log is undocked, you can dock it by dragging the tab (and reloading your UI) or by resetting the chat windows (from the chat menu)."] = "전투 기록이 숨겨집니다.|n|n이 옵션이 작동하려면 전투 기록이 활성화되어 있어야 합니다.|n|n전투 기록이 고정 해제된 경우, 탭을 드래그하여 (UI를 재시작해야 함) 또는 채팅 창을 재설정 (채팅 메뉴에서) 하여 고정할 수 있습니다."
	L["If checked, the day and night indicator will be hidden."] = "낮/밤 표시기가 숨겨집니다."
	L["If checked, the editbox will be moved to the top of the chat frame."] = "채팅 입력란이 프레임 상단으로 이동됩니다."
	L["If checked, the flight progress bar background texture will be shown."] = "비행 진행률 바 배경 텍스처가 표시됩니다."
	L["If checked, the flight progress bar background will fill instead of drain."] = "비행 진행률 바 배경이 비어있는 대신 채워집니다."
	L["If checked, the flight progress bar destination will be shown."] = "비행 진행률 바에 목적지가 표시됩니다."
	L["If checked, the grey screen of death and the netherworld effect will be disabled."] = "죽음의 회색 화면과 유령 효과가 비활성화됩니다."
	L["If checked, the health bar will not be shown."] = "체력바가 표시되지 않습니다."
	L["If checked, the interface button sound, the chat frame tab click sound and the game menu toggle sound will be muted."] = "인터페이스 버튼 소리, 채팅창 탭 클릭 소리, 게임 메뉴 전환 소리가 음소거됩니다."
	L["If checked, the Looking for Group button will be hidden while you are not queued.|n|nThis only applies to game realms with a Looking for Group feature."] = "대기열에 등록되지 않은 상태에서는 파티 찾기 버튼이 숨겨집니다.|n|n이는 파티 찾기 기능이 있는 게임 서버에만 적용됩니다."
	L["If checked, the main bar gryphons will not be shown."] = "행동 단축바 그리폰은 표시되지 않습니다."
	L["If checked, the minimap shape will be square.|n|nMinimap rotation (a setting in Edit Mode) is not recommended with a square minimap."] = "미니맵을 사각형으로 표시합니다.|n|n사각형 미니맵에서는 미니맵 회전(편집 모드 설정)을 권장하지 않습니다."
	L["If checked, the number of free bag slots will be shown in the backpack button icon and tooltip."] = "여유 가방 칸 수는 가방 버튼 아이콘과 툴팁에 표시됩니다."
	L["If checked, the player frame background will be shown in class color."] = "플레이어 프레임 배경은 직업 색상으로 표시됩니다."
	L["If checked, the player frame group indicator and the group labels displayed above the compact raid frames and the pullout raid frames will be hidden."] = "플레이어 프레임 파티 표시기와 공격대 프레임 위에 표시되는 파티 라벨이 숨겨집니다."
	L["If checked, the professions frame will be larger."] = "전문 기술창이 더 커집니다."
	L["If checked, the quest difficulty will be shown next to the quest level in the quest log list.|n|nThis will indicate whether the quest requires a group (+), dungeon (D), raid (R) or PvP (P).|n|nThe quest difficulty will always be shown in the quest log detail pane regardless of this setting."] = "퀘스트 난이도는 퀘스트 창에서 퀘스트 레벨 옆에 표시됩니다.|n|n이는 퀘스트가 파티 (+), 던전 (D), 공격대 (R) 또는 PvP (P) 를 요구하는지 여부를 나타냅니다.|n|n이 설정과 무관하게 퀘스트 난이도는 항상 퀘스트 상세 창에 표시됩니다."
	L["If checked, the quest log frame will be larger and feature a world map button and quest levels."] = "퀘스트 창이 더 커지고 세계 지도 버튼과 퀘스트 레벨이 표시됩니다."
	L["If checked, the quest log frame will be larger."] = "퀘스트 창이 더 커집니다."
	L["If checked, the ready check sound will be muted."] = "준비 확인 소리가 음소거됩니다."
	L["If checked, the remaining flight time will be spoken using text to speech.|n|nChanges to this setting will take effect on the next flight you take."] = "남은 비행 시간은 텍스트 음성 변환 기능을 통해 음성으로 안내됩니다.|n|n이 설정 변경 사항은 다음 비행 시 적용됩니다."
	L["If checked, the screen glow will be disabled.|n|nEnabling this option will also disable the drunken haze effect."] = "화면 반짝임 효과가 비활성화됩니다.|n|n이 옵션을 활성화하면 취한 듯한 흐릿함 효과도 함께 비활성화됩니다."
	L["If checked, the skill trainer frame will be larger and feature a train all skills button."] = "스킬 창이 더 커지고 모든 스킬 배우기 버튼이 추가됩니다."
	L["If checked, the spell fizzle sounds will be muted."] = "주문이 실패하는 소리가 음소거됩니다."
	L["If checked, the stance bar will not be shown."] = "태세 바가 표시되지 않습니다."
	L["If checked, the target frame background and focus frame background will be shown in class color."] = "대상 프레임 배경과 주시 프레임 배경은 직업 색상으로 표시됩니다."
	L["If checked, the tooltip will be color coded and you will be able to modify the tooltip layout and scale."] = "툴팁은 색상으로 구분되며, 툴팁 위치와 크기를 수정할 수 있습니다."
	L["If checked, the tracking button will be hidden while the pointer is not over the minimap."] = "커서가 미니맵 위에 있지 않으면 추적 버튼이 숨겨집니다."
	L["If checked, the vendor price will be shown in item tooltips."] = "판매 가격은 아이템 툴팁에 표시됩니다."
	L["If checked, the zone text bar will be hidden."] = "지역 텍스트 정보를 숨깁니다."
	L["If checked, the zoom buttons will be hidden.  You can use the mousewheel to zoom regardless of this setting."] = "줌 버튼이 숨겨집니다. 이 설정과 관계없이 마우스 휠을 사용하여 줌 할 수 있습니다."
	L["If checked, tooltips for world units will be hidden during combat."] = "전투 중에는 툴팁이 숨겨집니다."
	L["If checked, train sounds will be muted."] = "기차 소리가 음소거됩니다."
	L["If checked, unit targets will be shown."] = "유닛의 대상을 표시합니다."
	L["If checked, when you change the audio output device in your operating system, the game audio output device will change automatically as long as a cinematic is not playing at the time.|n|nFor this to work, the game audio output device will be set to system default."] = "운영 체제에서 소리 출력 장치를 변경하면 당시 시네마틱이 재생 중이 아닌 경우 게임 소리 출력 장치가 자동으로 변경됩니다.|n|n이를 위해 게임 소리 출력 장치는 시스템 기본값으로 설정됩니다."
	L["If checked, Wowhead links will be shown above the quest log frame."] = "퀘스트 창 위에 Wowhead 링크가 표시됩니다."
	L["If checked, Wowhead links will go directly to the comments section."] = "Wowhead 링크는 댓글 항목으로 바로 연결됩니다."
	L["If checked, yawns from hunter pet cats will be muted."] = "사냥꾼의 고양이 애완동물 하품하는 소리는 음소거됩니다."
	L["If checked, you can block drunken spam and duel spam."] = "취한 상태 메시지와 결투 메시지를 차단할 수 있습니다."
	L["If checked, you can hold down the alt key while opening a gossip window to automatically select a single gossip item.|n|nIf the gossip item type is banker, taxi, trainer, vendor or battlemaster, gossip will be skipped without needing to hold the alt key.  You can hold the shift key down to prevent this."] = "Alt 키를 누른 상태에서 대화 창을 열면 대화 항목이 자동으로 선택됩니다.|n|n대화 항목 유형이 은행원, 비행 경로, 기술사, 상인 또는 지휘관인 경우 Alt 키를 누를 필요 없이 대화를 건너뜁니다. Shift 키를 누르면 이를 방지할 수 있습니다."
	L["If checked, you can hold down the control key and click a chat tab to view recent chat in a copy-friendly window."] = "Ctrl 키를 누른 상태에서 채팅 탭을 클릭하면 복사하기 편한 창에서 최근 채팅 내용을 볼 수 있습니다."
	L["If checked, you can hold shift while tooltips are hidden to show them temporarily."] = "툴팁이 숨겨진 상태에서 Shift 키를 누르면 툴팁이 일시적으로 표시됩니다."
	L["If checked, you can press the arrow keys to move the insertion point left and right in the chat frame.|n|nIf unchecked, the arrow keys will use the default keybind setting."] = "화살표 키를 눌러 채팅 입력란에서 삽입점을 좌우로 이동할 수 있습니다.|n|n체크 해제 시 화살표 키는 기본 단축키 설정을 사용합니다."
	L["If checked, you can specify an edit mode layout that will always be applied when you login to any character."] = "어떤 캐릭터로 접속하든 항상 적용될 편집 모드 레이아웃을 지정할 수 있습니다."
	L["If checked, you will be able to cancel cinematics without being prompted for confirmation."] = "확인 메시지 없이 시네마틱을 취소할 수 있습니다."
	L["If checked, you will be able to change the font size of book text."] = "책 텍스트의 글꼴 크기를 변경할 수 있습니다."
	L["If checked, you will be able to change the font size of quest text."] = "퀘스트 텍스트의 글꼴 크기를 변경할 수 있습니다."
	L["If checked, you will be able to change the font size of standard mail text.|n|nThis does not affect mail created using templates (such as auction house invoices)."] = "우편 텍스트의 글꼴 크기를 변경할 수 있습니다.|n|n형식(경매장 등)을 사용하여 생성된 우편에는 영향을 미치지 않습니다."
	L["If checked, you will be able to change the position and scale of the timer bar.|n|nThe timer bar is used for showing remaining breath when underwater as well as other things."] = "타이머 바의 위치와 크기를 변경할 수 있습니다.|n|n타이머 바는 물속에서 남은 호흡을 표시하는 데 사용되며, 기타 여러 가지 용도로도 사용됩니다."
	L["If checked, you will be able to change the position and scale of the widget frame.|n|nThe widget frame is commonly used for showing PvP scores and tracking objectives."] = "프레임 위젯의 위치와 크기를 변경할 수 있습니다.|n|n프레임 위젯은 일반적으로 PvP 점수 및 추적 목표를 표시하는 데 사용됩니다."
	L["If checked, you will be able to customise the flight map."] = "비행 지도를 사용자 정의할 수 있습니다."
	L["If checked, you will be able to customise the minimap."] = "미니맵을 사용자 정의할 수 있습니다."
	L["If checked, you will be able to drag the chat frame to the edge of the screen."] = "채팅창을 화면 가장자리로 끌 수 있습니다."
	L["If checked, you will be able to mute a selection of game sounds."] = "게임 소리 중 일부를 음소거할 수 있습니다."
	L["If checked, you will be able to mute a selection of mount sounds."] = "일부 탈것 소리를 음소거할 수 있습니다."
	L["If checked, you will be able to mute your own choice of sounds."] = "원하는 소리를 직접 선택하여 음소거할 수 있습니다."
	L["If checked, you will be able to pan (right-button) and zoom (mousewheel) in the character frame, dressup frame and inspect frame.|n|nA toggle stats button will be shown in the character frame.  You can also middle-click the character model to toggle stats.|n|nModel rotation controls will be hidden.  Buttons to toggle gear will be added to the dressup frame."] = "캐릭터 프레임, 의상실 프레임, 비교 프레임에서 이동(오른쪽 버튼) 및 줌(마우스 휠)이 가능해집니다.|n|n캐릭터 프레임에 능력치 전환 버튼이 표시됩니다. 캐릭터 모델을 마우스 가운데 버튼 클릭하여도 능력치를 전환할 수 있습니다.|n|n모델 회전 컨트롤은 숨겨집니다. 의상실 프레임에 장비 전환 버튼이 추가됩니다."
	L["If checked, you will be able to place up to five beneficial cooldown icons above the target frame."] = "대상 프레임 위에 최대 5개의 재사용 대기시간 아이콘을 배치할 수 있습니다."
	L["If checked, you will be able to set some additional rules for when your character is automatically dismounted."] = "캐릭터가 자동으로 탈것에서 내리는 시점에 대해 몇 가지 추가 규칙을 설정할 수 있습니다."
	L["If checked, you will be able to set the density of weather effects."] = "날씨 효과의 밀도를 설정할 수 있습니다."
	L["If checked, you will be able to show a rare, elite or rare elite chain around the player frame."] = "플레이어 프레임 주위에 희귀, 정예 또는 희귀 정예 문양를 표시할 수 있습니다."
	L["If checked, you will be able to show customisable borders around the edges of the screen.|n|nThe borders are placed on top of the game world but under the UI so you can place UI elements over them."] = "화면 가장자리에 사용자 정의 가능한 테두리를 표시할 수 있습니다.|n|n테두리는 게임 인터페이스 위에 배치되지만 UI 아래에 위치하므로 UI 요소를 그 위에 배치할 수 있습니다."
	L["If checked, you will be able to zoom out to a greater distance."] = "더 먼 거리까지 확대해서 볼 수 있게 됩니다."
	L["If checked, you will be dismounted when you attempt to cast a non-instant cast spell while moving."] = "이동 중일 때 즉시 시전 주문이 아닌 주문을 시전하려고 하면 탈것에서 내리게 됩니다."
	L["If checked, you will be dismounted when you attempt to cast a spell but don't have the rage, mana or energy to cast it."] = "주문을 시전하려 할 때 분노, 마나 또는 기력이 부족하면 탈것에서 내리게 됩니다."
	L["If checked, you will be dismounted when you instruct a flight master to open the flight map."] = "비행 조련사에게 비행 지도를 열도록 지시하면 탈것에서 내리게 됩니다."
	L["If checked, you will be prompted to submit missing flight times."] = "누락된 비행 시간을 제출하라는 메시지가 표시됩니다."
	L["If checked, you will need to hold the override key down for quests to be automated.|n|nIf unchecked, holding the override key will prevent quests from being automated."] = "퀘스트를 자동화하려면 재정의 키를 누르고 있어야 합니다.|n|n체크 해제 시 재정의 키를 누르고 있으면 퀘스트가 자동화되지 않습니다."
	L["If checked, you will no longer need to type delete when destroying a superior quality item.|n|nIn addition, item links will be shown in all item destroy confirmation windows."] = "아이템을 파괴할 때 명령어를 입력할 필요가 없습니다.|n|n또한 모든 아이템 파괴 확인 창에 아이템 링크가 표시됩니다."
	L["If checked, you will not release automatically in Alterac Valley."] = "알터랙 계곡에서 자동으로 부활되지 않습니다."
	L["If checked, you will release automatically after you die in a battleground.|n|nYou will not release automatically if you have the ability to self-resurrect."] = "전장에서 사망하면 자동으로 부활됩니다.|n|n자가 부활 능력이 있는 경우 자동으로 부활되지 않습니다."
	L["If checked, your bags will not be opened or closed automatically when you interact with a merchant, bank or mailbox."] = "상인, 은행 또는 우체통과 상호 작용할 때 가방이 자동으로 열리거나 닫히지 않습니다."
	L["If checked, your chat history will increase to 4096 lines.  If unchecked, the default will be used (128 lines).|n|nEnabling this option may prevent some chat text from showing during login."] = "채팅 기록이 4096줄로 늘어납니다. 선택하지 않으면 기본값(128줄)이 적용됩니다.|n|n이 옵션을 활성화하면 로그인 중 일부 채팅 내용이 표시되지 않을 수 있습니다."
	L["If checked, your gear will be repaired automatically when you visit a suitable merchant.|n|nYou can hold the shift key down when you talk to a merchant to override this setting."] = "적합한 상인을 방문하면 장비가 자동으로 수리됩니다.|n|n상인과 대화할 때 시프트 키를 누르고 있으면 이 설정을 무시할 수 있습니다."
	L["If checked, zone text will not be shown (eg. 'Ironforge')."] = "지역 텍스트(예: ‘아이언포지’)는 표시되지 않습니다."
	L["If the edit mode layout name that you enter here exists, that layout will be applied when you login to any character on your account."] = "여기에 입력한 편집 모드 레이아웃 이름이 존재하면, 계정의 어떤 캐릭터로 접속하든 해당 레이아웃이 적용됩니다."
	L["If you use the 'Hide addon buttons' or 'Minimap button bag' settings but you want some addon buttons to remain visible around the minimap, enter the button names into the editbox below separated by commas.|n|nChanges will require a UI reload to take effect."] = "'애드온 버튼 숨기기' 또는 '미니맵 버튼 모음' 설정을 사용하지만 미니맵 주변에 일부 애드온 버튼이 계속 표시되도록 하려면 아래 편집 상자에 버튼 이름을 쉼표로 구분하여 입력하세요.|n|n변경 사항을 적용하려면 UI를 새로고침해야 합니다."
	L["If you want to listen to a sound file, enter the sound file ID into the editbox and click the play button.|n|nYou can scroll the mousewheel over the editbox to play neighbouring sound files."] = "소리 파일을 재생하려면 소리 파일 ID를 입력란에 입력하고 재생 버튼을 클릭하세요.|n|n입력란 위에서 마우스 휠을 스크롤하면 인접한 소리 파일을 재생할 수 있습니다."
	L["Incompatible"] = "호환되지 않음"
	L["Increase chat history"] = "채팅 기록 증가"
	L["Interface"] = "인터페이스"
