	L["Keep audio synced"] = "오디오 동기화 유지"
	L["Key missing!"] = "키가 없습니다!"
	L["Keyword"] = "키워드"
	L["Larger quest log frame"] = "더 큰 퀘스트 창"
	L["Launch the developer console with a large font."] = "큰 글꼴로 개발자 콘솔을 실행합니다."
	L["Lava"] = "용암"
	L["Layout name"] = "레이아웃 이름"
	L["Leatrix Plus"] = "Leatrix Plus"
	L["Leatrix Plus Help"] = "Leatrix Plus 도움말"
	L["Leatrix Plus needs to be updated with the flight details.  Press CTRL/C to copy the flight details below then paste them into an email to flight@leatrix.com.  When your report is received, Leatrix Plus will be updated and you will never see this window again for this flight."] = "Leatrix Plus에 비행 정보를 업데이트해야 합니다. 아래 비행 정보를 복사하려면 CTRL/C를 누른 후 flight@leatrix.com으로 이메일에 붙여넣으십시오. 보고서가 접수되면 Leatrix Plus가 업데이트되며 해당 비행 대해 이 창이 다시 표시되지 않습니다."
	L["Leatrix Plus will not overwrite LeaPlusDB at next logout."] = "Leatrix Plus는 다음 로그 아웃시 LeaPlusDB를 덮어 쓰지 않습니다."
	L["LEATRIX PLUS: WRONG VERSION INSTALLED!"] = "LEATRIX PLUS: 잘못된 버전이 설치되었습니다!"
	L["Left"] = "왼쪽"
	L["Left-drag"] = "왼쪽 끌기"
	L["Legion"] = "군단"
	L["Level"] = "레벨"
	L["Levels"] = "레벨"
	L["Links go directly to the comments section"] = "링크는 댓글 항목으로 바로 연결"
	L["Loch Modan"] = "모단 호수"
	L["Login"] = "로그인"
	L["Low"] = "낮음"
